ee:variables.ee:set-variable:
%dw 2.0
output application/java
var response = read(payload as String {encoding: "windows-1252"}, "application/xml")
var cursor = response.TBL.@next default null
---
{
	data: response.TBL.*Stk default [],
	next:
		if (cursor == null or isBlank(cursor as String))
			null
		else
			cursor as String
}
